style.css:
@-moz-document domain("chatgpt.com"), domain("chat.openai.com") {
html,
  body,
  button,
  textarea,
  input,
  select {
    font-family: "Egg9TheNeatFont", "Noto Sans KR", "Malgun Gothic", "Apple SD Gothic Neo", "Segoe UI", sans-serif !important;
  }

  .markdown,
  .prose,
  article {
    font-family: "Egg9TheNeatFont", "Noto Sans KR", "Malgun Gothic", "Apple SD Gothic Neo", sans-serif !important;
    line-height: 1.75 !important;
    letter-spacing: -0.01em !important;
  }

  textarea {
    font-family: "Egg9TheNeatFont", "Noto Sans KR", "Malgun Gothic", "Apple SD Gothic Neo", sans-serif !important;
    line-height: 1.6 !important;
  }

  code,
  pre,
  kbd,
  samp {
    font-family: "D2Coding", "Consolas", "Courier New", monospace !important;
  }
}
